/**
 * manFigure — the man on the backdrop (doc 180): his portrait (generated by the
 * OS's image model, then aligned on the portrait frame by
 * scripts/portrait-density-map.py) and its landmarks, measured on the aligned
 * photo; portraitFigure does the rest.
 *
 * @module avatar/manFigure
 */
import { createPortraitFigure, type PortraitSpec } from './portraitFigure';
// The map is fetched when the face is worn (portraitMaps); the spec reads it there.
import { portraitMap } from './portraitMaps';

export const MAN_SPEC: PortraitSpec = {
  // His particles take the photo's own colours (the first try of a more lifelike face).
  get map() { return portraitMap('man'); },
  mid: { x: 257, y: 380 },
  // Narrower openings than hers: his eyes are set deeper and less open.
  eyes: [{ x: 182, y: 284, rx: 31, ry: 12 }, { x: 331, y: 286, rx: 31, ry: 12 }],
  iris: { outer: 15, inner: 5.5, lookX: 10, lookY: 4 },
  mouth: { x: 256, y: 455, rx: 63, ry: 34 },
  brows: [
    [[228, 258], [210, 255], [190, 254], [170, 253], [150, 255], [135, 258]],
    [[285, 258], [300, 256], [320, 254], [340, 253], [360, 254], [375, 255], [390, 259]],
  ],
  cheeks: [[185, 375], [330, 375]],
  nose: { x: 257, y: 385, bridgeTop: 295 },
  chinY: 560,
  pivotY: 600,
  neckBaseY: 615,
  neckHalf: 120,
  shoulderHalf: 260,
  // Short hair, close to the skull: it moves with the head, its tips barely stir.
  hair: { cx: 257, cy: 120, rx: 210, ry: 200, depth: 0.62, still: 1.1, sway: 0.08 },
  // Shorter, fewer lashes than hers.
  lashes: { count: 11, long: 12, short: 4 },
};

export const MAN = createPortraitFigure(MAN_SPEC);
